d='        {isLoading ? <div className="py-12 flex justify-center"><Spinner size="lg" /></div> : error ? <div className="p-8 text-red-600">{error}</div> : todayAppts.length === 0 ? <div className="p-8 text-center text-neutral-500"><Calendar className="w-12 h-12 mx-auto mb-3 opacity-50" /><p>No appointments today</p></div> : (\n          <table className="w-full"><thead className="bg-neutral-50 border-b"><tr><th className="text-left px-4 py-3 text-xs uppercase">Patient</th><th className="text-left px-4 py-3 text-xs uppercase">Time</th><th className="text-left px-4 py-3 text-xs uppercase">Type</th><th className="text-left px-4 py-3 text-xs uppercase">Status</th><th className="text-left px-4 py-3 text-xs uppercase">Actions</th></tr></thead><tbody className="divide-y">{todayAppts.map((apt) => (<tr key={apt.id} className="hover:bg-neutral-50"><td className="px-4 py-3"><Link to={"/dentist/patients/" + apt.patient_id} className="font-medium text-primary-700">{apt.patient_name || \'Patient\'}</Link></td><td className="px-4 py-3 text-sm">{apt.start}{apt.end_time && " - " + apt.end_time}</td><td className="px-4 py-3 text-sm">{type(apt.type)}</td><td className="px-4 py-3">{badge(apt.status)}</td><td className="px-4 py-3"><Link to={"/dentist/patients/" + apt.patient_id}><Button variant="ghost" size="sm"><Eye className="w-4 h-4" /></Button></Link></td></tr>))}</tbody></table>\n        )}\n      </Card>\n      <Card>\n        <div className="flex items-center justify-between p-4 border-b"><h2 className="font-semibold">Upcoming</h2><Link to="/dentist/appointments"><Button variant="ghost" size="sm">View All</Button></Link></div>\n        {upcoming.length === 0 ? <div className="p-8 text-center text-neutral-500">No upcoming appointments</div> : (<div className="divide-y">{upcoming.map((apt) => (<div key={apt.id} className="flex items-center justify-between p-4"><div className="flex items-center gap-4"><div className="w-10 h-10 rounded-lg bg-primary-100 flex items-center justify-center text-primary-700 font-medium">{apt.patient_name?.[0] || \'P\'}</div><div><p className="font-medium">{apt.patient_name || \'Patient\'}</p><p className="text-sm text-neutral-500">{type(apt.type)}</p></div></div><div className="text-right"><p className="font-medium">{apt.date && new Date(apt.date).toLocaleDateString()}</p><p className="text-sm text-neutral-500">{apt.start}</p></div></div>))}</div>)}\n      </Card>\n    </div>\n  )\n}'
n=open('e:/DENTALAIAGENT/frontend/src/pages/dentist/DentistDashboardPage.tsx','a',encoding='utf-8')
